#include "bell_generator.h"
#include "excitation/meridional_influence.hpp"
#include "fem/internal_modal_solver.hpp"
#include "fem/cylindrical_modal_field.hpp"

#include <algorithm>
#include <array>
#include <cmath>
#include <fstream>
#include <iomanip>
#include <iostream>
#include <sstream>
#include <string>
#include <vector>

using namespace BellOptimizer;
using namespace BellOptimizer::FEM;
namespace {
constexpr int kModes=5;
struct Level{int layers=0;BellMeshData mesh_mm,mesh_si;ModalData modes;std::vector<std::vector<double>> fields;};
std::vector<std::string> split(const std::string&s){std::vector<std::string>v;std::stringstream ss(s);std::string x;while(std::getline(ss,x,','))v.push_back(x);return v;}
BellGeometry geometryFrom(const std::vector<std::string>&f){BellGeometry g;g.H=std::stod(f[2]);g.R_mouth=std::stod(f[3]);g.t_top=std::stod(f[4]);g.t_bottom=std::stod(f[5]);g.r_knots={0.0,std::stod(f[6]),std::stod(f[7]),std::stod(f[8]),1.0};g.ellipticity=std::stod(f[9]);return g;}
bool makeLevel(const BellMeshData&base,int n,int layers,const BellMaterial&mat,Level&out){BellMeshData mesh;mesh.outer_profile=base.outer_profile;mesh.inner_profile=base.inner_profile;mesh.total_arc_length=base.total_arc_length;mesh.min_thickness=base.min_thickness;mesh.max_thickness=base.max_thickness;mesh.nodes.reserve(std::size_t(n)*std::size_t(layers+1));mesh.elements.reserve(std::size_t(n-1)*std::size_t(layers));for(int l=0;l<=layers;++l){double a=double(l)/layers;for(int i=0;i<n;++i){const auto&o=base.outer_profile[std::size_t(i)];const auto&in=base.inner_profile[std::size_t(i)];Node node;node.id=int(mesh.nodes.size())+1;node.r=o.r+a*(in.r-o.r);node.z=o.z+a*(in.z-o.z);mesh.nodes.push_back(node);}}for(int l=0;l<layers;++l){int ro=l*n,ri=(l+1)*n;for(int i=0;i<n-1;++i){Element e;e.n1=ri+i+1;e.n2=ro+i+1;e.n3=ro+i+2;e.n4=ri+i+2;mesh.elements.push_back(e);}}out.layers=layers;out.mesh_mm=std::move(mesh);out.mesh_si=out.mesh_mm;for(auto&node:out.mesh_si.nodes){node.r*=1e-3;node.z*=1e-3;}InternalModalSolver solver(true,kModes,true);Excitation::MeridionalInfluence influence;ModalProblem p{out.mesh_mm,mat,".","round_thickness_mass",&influence};if(!solver.solve(p,out.modes)||out.modes.modes.size()<kModes)return false;out.fields.resize(kModes);for(int m=0;m<kModes;++m){const auto&mode=out.modes.modes[std::size_t(m)];if(mode.nodal_radial.size()!=out.mesh_si.nodes.size()||mode.nodal_axial.size()!=out.mesh_si.nodes.size())return false;auto&v=out.fields[std::size_t(m)];v.assign(out.mesh_si.nodes.size()*3u,0.0);for(std::size_t i=0;i<out.mesh_si.nodes.size();++i){v[i*3u]=mode.nodal_radial[i];v[i*3u+2u]=mode.nodal_axial[i];}}return true;}
int bitCount(unsigned x){int n=0;while(x){n+=int(x&1u);x>>=1u;}return n;}
struct Metrics{std::array<int,kModes>assignment{};double min_overlap=1,mean_overlap=0,min_coverage=1,max_freq_error=0;};
Metrics compareLevels(const Level&a,const Level&b,double density){std::vector<int>h{0};std::array<std::array<double,kModes>,kModes>score{};std::array<std::array<CylindricalModalFieldOverlap,kModes>,kModes>ov{};for(int i=0;i<kModes;++i)for(int j=0;j<kModes;++j){CylindricalModalField fa{&a.mesh_si,&h,&a.fields[std::size_t(i)],1.0,density};CylindricalModalField fb{&b.mesh_si,&h,&b.fields[std::size_t(j)],1.0,density};ov[i][j]=compare_cylindrical_modal_fields(fa,fb,64,0.98);if(!ov[i][j].valid)throw std::runtime_error("invalid cross-mesh mass overlap");score[i][j]=ov[i][j].normalized_overlap;}
constexpr int states=1<<kModes;std::array<double,states>dp;std::array<int,states>prev{},choice{};dp.fill(-1e100);dp[0]=0;for(int mask=0;mask<states;++mask){int row=bitCount(unsigned(mask));if(row>=kModes||dp[mask]<-1e90)continue;for(int j=0;j<kModes;++j)if(!(mask&(1<<j))){int next=mask|(1<<j);double v=dp[mask]+score[row][j];if(v>dp[next]){dp[next]=v;prev[next]=mask;choice[next]=j;}}}Metrics out;int mask=states-1;for(int i=kModes-1;i>=0;--i){out.assignment[i]=choice[mask];mask=prev[mask];}double sum=0;for(int i=0;i<kModes;++i){int j=out.assignment[i];const auto&o=ov[i][j];out.min_overlap=std::min(out.min_overlap,o.normalized_overlap);out.min_coverage=std::min(out.min_coverage,o.common_volume_fraction);sum+=o.normalized_overlap;double fc=a.modes.modes[i].frequency_hz,ff=b.modes.modes[j].frequency_hz;out.max_freq_error=std::max(out.max_freq_error,std::abs(ff-fc)/std::max(std::abs(ff),1e-12));}out.mean_overlap=sum/kModes;return out;}
}
int main(int argc,char**argv){const std::string input=argc>1?argv[1]:"round_geometry_dataset.csv",output=argc>2?argv[2]:"round_geometry_thickness_mass.csv";const int n=argc>3?std::stoi(argv[3]):41;std::ifstream in(input);if(!in)return 1;std::string line;std::getline(in,line);std::ofstream csv(output);if(!csv)return 2;csv<<"geometry_index,tag,profile_nodes,coarse_layers,fine_layers,min_fullfield_overlap,mean_fullfield_overlap,min_common_volume_fraction,max_matched_frequency_change,assignment\n"<<std::setprecision(12);BellMaterial mat;const double density=mat.rho*1e12;const std::vector<int>selected{0,1,3};int geometries=0,failures=0;double global_min=1,global_maxerr=0,global_cov=1;while(std::getline(in,line)){if(line.empty())continue;const auto f=split(line);if(f.size()<17||f[16]!="PASS")continue;int id=std::stoi(f[0]);if(std::find(selected.begin(),selected.end(),id)==selected.end())continue;const auto g=geometryFrom(f);BellMeshConfig cfg;cfg.nNodes=n;BellGenerator gen(mat,cfg);gen.setGeometry(g);GeometryValidationResult vr;if(!gen.buildMesh(&vr)){++failures;std::cerr<<"BASE_FAIL "<<id<<' '<<vr.reason<<'\n';continue;}const auto base=gen.getMeshData();std::vector<Level>levels;bool ok=true;for(int layers:{1,2,3,4}){Level l;if(!makeLevel(base,n,layers,mat,l)){ok=false;break;}levels.push_back(std::move(l));}if(!ok){++failures;std::cerr<<"SOLVE_FAIL "<<id<<'\n';continue;}++geometries;for(std::size_t p=1;p<levels.size();++p){const auto m=compareLevels(levels[p-1],levels[p],density);global_min=std::min(global_min,m.min_overlap);global_cov=std::min(global_cov,m.min_coverage);global_maxerr=std::max(global_maxerr,m.max_freq_error);csv<<id<<','<<f[1]<<','<<n<<','<<levels[p-1].layers<<','<<levels[p].layers<<','<<m.min_overlap<<','<<m.mean_overlap<<','<<m.min_coverage<<','<<m.max_freq_error<<",\"";for(int i=0;i<kModes;++i)csv<<(i?";":"")<<(i+1)<<"->"<<(m.assignment[i]+1);csv<<'"'<<'\n';}}
std::cout<<"profile_nodes="<<n<<" geometries="<<geometries<<" failures="<<failures<<" min_fullfield_overlap="<<global_min<<" min_common_volume="<<global_cov<<" max_matched_frequency_change_percent="<<global_maxerr*100<<'\n';return geometries>0&&failures==0&&csv?0:3;}
